import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'

export async function PUT(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const body = await req.json()
  const existing = await db.treatment.findUnique({ where: { id } })
  if (!existing) {
    return NextResponse.json({ error: 'Treatment not found' }, { status: 404 })
  }
  const start = body.start ?? existing.start
  const end = body.end ?? existing.end
  if (start >= end) {
    return NextResponse.json({ error: 'End must be after start' }, { status: 400 })
  }
  const clash = await db.treatment.findFirst({
    where: { suiteId: existing.suiteId, status: 'booked', start: { lt: end }, end: { gt: start }, id: { not: id } },
  })
  if (clash) {
    return NextResponse.json({ error: 'Time conflict with an existing treatment' }, { status: 409 })
  }
  const updated = await db.treatment.update({
    where: { id },
    data: { title: body.title ?? existing.title, start, end },
  })
  return NextResponse.json({ treatment: updated })
}

export async function DELETE(
  _req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const existing = await db.treatment.findUnique({ where: { id } })
  if (!existing) {
    NextResponse.json({ error: 'Treatment not found' }, { status: 404 })
    return
  }
  const cancelled = await db.treatment.update({
    where: { id },
    data: { status: 'cancelled' },
  })
  return NextResponse.json({ treatment: cancelled })
}


